import { bounded } from './bounded.js';

/**
 * Every form a known value can take in what the host persists.
 *
 * The guard's own transport is JSON, so a value that contains a quote or a control
 * character reaches the diagnostic escaped; redacting only the plaintext form would
 * let a reader recover the value by parsing that fragment. The escaped variant is
 * generated by the host, not by user code, so it belongs to the exact-value boundary.
 */
function secretVariants(secrets: readonly string[]): string[] {
  const variants = new Set<string>();
  for (const secret of secrets) {
    if (secret.length === 0) continue;
    variants.add(secret);
    const escaped = JSON.stringify(secret).slice(1, -1);
    if (escaped !== secret) variants.add(escaped);
  }
  return [...variants].sort((left, right) => right.length - left.length);
}

/** Replace every exact occurrence of the given forms, including inside larger text. */
function replaceExact(text: string, variants: readonly string[]): string {
  let value = text;
  for (const variant of variants) value = value.split(variant).join('\0');
  return value.replaceAll('\0', '[REDACTED]');
}

/**
 * Replace every exact occurrence of a known value in either its plaintext or its
 * JSON-escaped form. This is exact-value protection, not a transformed-secret
 * boundary: a program can still encode a value some other way.
 */
export function redactExact(text: string, secrets: readonly string[]): string {
  return replaceExact(text, secretVariants(secrets));
}

const REDACTED_DETAIL_MAX_BYTES = 16 * 1024;
const REDACTED_STRING_MAX_BYTES = 1024;
// Deep enough for the supported diagnostic shape: detail -> cause -> cause detail ->
// attempts -> attempt -> guard -> field. Cycles remain bounded by this ceiling.
const REDACTED_DEPTH = 8;
const REDACTED_ENTRIES = 16;
const REDACTED_ITEMS = 8;

function redactedValue(value: unknown, variants: readonly string[], depth: number): unknown {
  if (typeof value === 'string') return bounded(replaceExact(value, variants), REDACTED_STRING_MAX_BYTES);
  if (typeof value === 'number' || typeof value === 'boolean' || value === null) return value;
  if (Array.isArray(value)) return depth >= REDACTED_DEPTH ? [] : value.slice(0, REDACTED_ITEMS).map(item => redactedValue(item, variants, depth + 1));
  if (typeof value === 'object') {
    if (depth >= REDACTED_DEPTH) return undefined;
    const result: Record<string, unknown> = {};
    for (const [key, item] of Object.entries(value as Record<string, unknown>).slice(0, REDACTED_ENTRIES)) {
      const next = redactedValue(item, variants, depth + 1);
      if (next !== undefined) result[key] = next;
    }
    return result;
  }
  return undefined;
}

/**
 * The same protection for a structured diagnostic detail, bounded in depth and
 * size so a command's raw output can never become an unbounded stored record.
 */
export function redactRecord(value: unknown, secrets: readonly string[]): Record<string, unknown> | undefined {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) return undefined;
  const variants = secretVariants(secrets);
  const result = redactedValue(value, variants, 0);
  if (result === undefined || typeof result !== 'object' || Array.isArray(result)) return undefined;
  const encoded = JSON.stringify(result);
  if (encoded === undefined) return undefined;
  if (new TextEncoder().encode(encoded).length <= REDACTED_DETAIL_MAX_BYTES) return result as Record<string, unknown>;
  return { truncated: true, preview: bounded(replaceExact(encoded, variants), REDACTED_STRING_MAX_BYTES) };
}
